class LandlordInstructionsList(BaseModel):
    __root__: list[LandlordInstruction]

instructions_list = query_ai_assistant(
    "Read the following text and extract all payment instructions from the landlord. For each instruction, extract the action (such as 'pay' or 'transfer'), the recipient (IBAN or name), the amount, the subject (reason for payment), and the date the payment should be made. If there are multiple instructions, return them all as a list.",
    LandlordInstructionsList
)

for instr in instructions_list.__root__:
    send_money(instr.recipient, instr.amount, instr.subject, instr.date)
