class LandlordInstructionsContainer(BaseModel):
    instructions: list[LandlordInstruction]

instructions_container = query_ai_assistant(
    "Read the following text and extract all payment instructions from the landlord. For each instruction, extract the action (such as 'pay' or 'transfer'), the recipient (IBAN or name), the amount, the subject (reason for payment), and the date the payment should be made. If there are multiple instructions, return them all as a list in the 'instructions' field.",
    LandlordInstructionsContainer
)

for instr in instructions_container.instructions:
    send_money(instr.recipient, instr.amount, instr.subject, instr.date)
